WITH unpacked AS (SELECT id, service, log_ts, level, latency_ms, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SHIFTRIGHT(status_code, 2) AS status_code_high, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region FROM app_logs) SELECT id, service, latency_ms, status_code_high, has_region, ROW_NUMBER() OVER w_grp AS seq_no, ROW_NUMBER() OVER w_recent AS event_seq, AVG(latency_ms) OVER (PARTITION BY level ORDER BY latency_ms ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS latency_ms_avg_2 FROM unpacked WINDOW w_grp AS (ORDER BY duration_sec DESC, id ASC), w_recent AS (ORDER BY log_ts ASC, id ASC);
